insert into public.reglas_firma (id, plan_id, minimo_teoria, minimo_laboratorio, minimo_asistencia, minimo_asistencia_lab, modo_laboratorio, notas) values ('5fad7d99-dd53-5108-b8be-bf7b26b3a5e7', 'f4027ad0-432a-5d3a-ae65-40e9859f0a9e', 50, 60, 60, 100, 'separado', 'Res. CSU 0108-00-2024 (Art. 43): parciales teóricos >= 50 % (o >= 60 % en recuperación), parciales prácticos >= 60 %, asistencia a teoría >= 60 % y 100 % de las prácticas aprobadas. PG = (teoría + práctica) / 2 (Art. 44). CF = 0,40 PG + 0,60 EF, con EF >= 60 % (Art. 57).') on conflict (id) do update set minimo_teoria = excluded.minimo_teoria, minimo_laboratorio = excluded.minimo_laboratorio, minimo_asistencia = excluded.minimo_asistencia, minimo_asistencia_lab = excluded.minimo_asistencia_lab, notas = excluded.notas;
