insert into public.reglas_firma (id, plan_id, minimo_teoria, minimo_laboratorio, minimo_asistencia, minimo_asistencia_lab, modo_laboratorio, notas) values ('a1bdd15b-b260-5052-943a-88028dfbe7b4', '3db2fe69-b28a-5826-882b-93cec452da8e', 50, 60, 60, 100, 'separado', 'Res. CSU 0108-00-2024 (Art. 43): parciales teóricos >= 50 % (o >= 60 % en recuperación), parciales prácticos >= 60 %, asistencia a teoría >= 60 % y 100 % de las prácticas aprobadas. PG = (teoría + práctica) / 2 (Art. 44). CF = 0,40 PG + 0,60 EF, con EF >= 60 % (Art. 57).') on conflict (id) do update set minimo_teoria = excluded.minimo_teoria, minimo_laboratorio = excluded.minimo_laboratorio, minimo_asistencia = excluded.minimo_asistencia, minimo_asistencia_lab = excluded.minimo_asistencia_lab, notas = excluded.notas;
